import { Context } from "effect";
/** The program call a built-in is running under: where to locate failures born inside it, and how deep the stack is there. */
export const CallSite = Context.Reference("codemode/CallSite", {
    defaultValue: () => ({ depth: 0 }),
});
export const AsyncIteratorSymbol = Symbol("codemode.async-iterator");
export const IteratorSymbol = Symbol("codemode.iterator");
export const IteratorSymbols = [AsyncIteratorSymbol, IteratorSymbol];
export class Throw {
    value;
    constructor(value) {
        this.value = value;
    }
}
export class GeneratorReturn {
    value;
    constructor(value) {
        this.value = value;
    }
}
export const OptionalShortCircuit = Symbol("codemode.optional-short-circuit");
/**
 * A failure raised by the interpreter or a built-in. It travels as a defect and becomes one program Error object
 * the first time a handler observes it, so every observer of the same failure sees the same value.
 */
export class PendingThrow {
    type;
    message;
    kind;
    suggestions;
    node;
    value;
    constructor(
    /** The JS error class a program sees when it catches this failure. */
    type, message, node, kind = "ExecutionFailure", suggestions) {
        this.type = type;
        this.message = message;
        this.kind = kind;
        this.suggestions = suggestions;
        if (node)
            this.node = node;
    }
}
const failure = (type, kind) => (message, node) => new PendingThrow(type, message, node, kind);
export const typeError = failure("TypeError");
export const invalidData = failure("TypeError", "InvalidDataValue");
export const rangeError = failure("RangeError");
export const referenceError = failure("ReferenceError");
export const syntaxError = failure("SyntaxError");
export const uriError = failure("URIError");
// Orient the agent rather than enumerate JavaScript; interpreter-support.md is the full matrix.
export const supportedSyntaxMessage = "This is a restricted JavaScript-like language. Supported: plain and async functions, data literals, destructuring, standard control flow, await and Promise, and built-ins such as Array, Object, Math, JSON, Date, RegExp, Map, Set, and URL. Unsupported: classes, getters/setters, BigInt, and custom Symbols. Use plain functions and data objects instead.";
export const unsupportedSyntax = (kind, node) => new PendingThrow("SyntaxError", `Syntax '${kind}' is not supported. ${supportedSyntaxMessage}`, node, "UnsupportedSyntax", [supportedSyntaxMessage]);
// Acorn lines are 1-based and its columns are 0-based. Diagnostics use 1-based columns of the submitted source.
export const sourceLocation = (node) => ({
    line: node.loc?.start.line ?? 1,
    column: (node.loc?.start.column ?? 0) + 1,
});
export const formatLocation = (node) => {
    if (!node?.loc)
        return "";
    const location = sourceLocation(node);
    return ` (line ${location.line}, col ${location.column})`;
};
